input.command:
cd /home/user/rork-app && echo "=== LIVE SNAPSHOT $(date -u +%Y-%m-%dT%H:%M:%SZ) ===" && echo "" && echo "--- SHAs ---" && echo "Local:     $(git log -1 --format='%h' 2>/dev/null)" && echo "GitHub:    $(git ls-remote origin HEAD 2>/dev/null | awk '{print substr($1,1,8)}')" && echo "Prod:      $(curl -sS https://api.ivxholding.com/version 2>/dev/null | bun -e "console.log(JSON.parse(require('fs').readFileSync('/dev/stdin','utf8')).commitShort)" 2>&1)" && echo "" && echo "--- Health core ---" && curl -sS https://api.ivxholding.com/health 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const p=d.ivxSeniorDeveloperProviderVerification||{};
console.log('status:', d.status);
console.log('provider:', p.providerState, 'http:', p.lastHttpStatus);
console.log('bootTime:', d.bootTime);
const qa=d.ivxSeniorDeveloperFinalQA||{};
console.log('aiProviderReady:', qa.aiProviderReady, 'liveWorkReady:', qa.liveWorkReady, 'ownerAuthorized:', qa.ownerAuthorized);
" 2>&1 && echo "" && echo "--- Endpoints HTTP codes ---" && for ep in /health /version /api/public/chat /api/ivx/owner-ai/status /api/video/capabilities; do printf "%-40s " "$ep"; curl -sS -o /dev/null -w "HTTP %{http_code} %{time_total}s\n" -X POST "https://api.ivxholding.com$ep" -H 'Content-Type: application/json' -d '{}' 2>/dev/null || curl -sS -o /dev/null -w "HTTP %{http_code} %{time_total}s\n" "https://api.ivxholding.com$ep" 2>/dev/null; done && echo "" && echo "--- Landing + chat ---" && curl -sS -o /dev/null -w "ivxholding.com: HTTP %{http_code} %{size_download}b %{time_total}s\n" https://ivxholding.com 2>/dev/null && curl -sS -o /dev/null -w "chat.ivxholding.com: HTTP %{http_code} %{size_download}b %{time_total}s\n" https://chat.ivxholding.com 2>/dev/null

