const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const p=d.ivxSeniorDeveloperProviderVerification||{};
const qa=d.ivxSeniorDeveloperFinalQA||{};
console.log('status:', d.status);
console.log('provider:', p.providerState, 'http:', p.lastHttpStatus);
console.log('bootTime:', d.bootTime);
console.log('aiProviderReady:', qa.aiProviderReady);
console.log('liveWorkReady:', qa.liveWorkReady);
console.log('ownerAuthorized:', qa.ownerAuthorized);
console.log('intentRouterReady:', qa.intentRouterReady);
" 2>&1

